package com.oms.supplychain.service.wms;

import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** Bounded read-only warehouse snapshots. Never invokes reconciliation, dispatch or inventory posting. */
@Service public class ReturnQueryWarehouse {
    @Resource WmsStore db;
    @Resource WmsTenantRoutes routes;
    private long n(Object v){return v==null?0:id(v);}
    public List<Map<String,Object>> changes(String c){routes.datasource(c);return db.jdbc.queryForList("SELECT owner_kind,source_id,work_version FROM wms_return_query_dirty WHERE company_code=? ORDER BY owner_kind,source_id LIMIT 100",c);}
    public void acknowledge(String c,List<Map<String,Object>> rows){routes.datasource(c);require(rows!=null&&rows.size()<=100,"一次最多确认100项查询变更");db.tx().execute(tx->{for(Map<String,Object> r:rows){require(Arrays.asList("REFUND","EXCHANGE").contains(text(r.get("owner_kind")))&&n(r.get("source_id"))>0&&n(r.get("work_version"))>0,"查询变更标识无效");db.jdbc.update("DELETE FROM wms_return_query_dirty WHERE company_code=? AND owner_kind=? AND source_id=? AND work_version=?",c,r.get("owner_kind"),r.get("source_id"),r.get("work_version"));}return null;});}
    public List<Map<String,Object>> snapshots(String c,List<Map<String,Object>> sources){
        routes.datasource(c);require(sources!=null&&sources.size()<=500,"一次最多查询500项退回来源");List<Map<String,Object>> out=new ArrayList<>();
        for(String kind:Arrays.asList("REFUND","EXCHANGE")){
            Set<Long> ids=new LinkedHashSet<>();for(Map<String,Object> s:sources){require(Arrays.asList("REFUND","EXCHANGE").contains(text(s.get("owner_kind")))&&n(s.get("source_id"))>0,"退回来源无效");if(kind.equals(s.get("owner_kind")))ids.add(n(s.get("source_id")));}if(ids.isEmpty())continue;
            String marks=String.join(",",Collections.nCopies(ids.size(),"?"));List<Object> args=new ArrayList<>();args.add(c);args.addAll(ids);boolean refund="REFUND".equals(kind);
            String legacy=refund?" LEFT JOIN wms_refund_parcel_member rm ON rm.company_code=t.company_code AND rm.task_id=t.id AND (rm.active=1 OR EXISTS(SELECT 1 FROM wms_refund_parcel_document saved WHERE saved.company_code=rm.company_code AND saved.parcel_id=rm.parcel_id AND saved.generation=rm.generation)) LEFT JOIN wms_refund_parcel rp ON rp.company_code=rm.company_code AND rp.id=rm.parcel_id LEFT JOIN wms_refund_parcel_document rd ON rd.company_code=rm.company_code AND rd.parcel_id=rm.parcel_id AND rd.generation=rm.generation":"";
            String legacyColumns=refund?",rm.parcel_id rpid,rp.parcel_sn rpsn,rp.carrier_code rpcarrier,rp.waybill rpwaybill,rp.create_time rpcreated,rp.dispatch_after rpdue,rd.return_sn rdsn,rd.ticket_id rdticket,rd.dispatch_state rddispatch,rd.cancel_state rdcancel,rd.external_order rdexternal,rd.last_error rderror,rd.create_time rdcreated,rd.warehouse_status rdstatus,(SELECT COUNT(DISTINCT rc.plan_id) FROM wms_refund_parcel_member rc WHERE rc.company_code=rm.company_code AND rc.parcel_id=rm.parcel_id) rpcount,(SELECT COUNT(*) FROM wms_refund_parcel_receipt rr WHERE rr.company_code=rm.company_code AND rr.parcel_id=rm.parcel_id AND rr.state='WAIT_ALLOCATION') rppending":"";
            List<Map<String,Object>> values=db.jdbc.queryForList("SELECT t.*,(SELECT COUNT(*) FROM "+(refund?"wms_refund_return_review":"wms_exchange_return_review")+" rv WHERE rv.company_code=t.company_code AND rv.task_id=t.id AND rv.state='WAIT_REVIEW') source_pending,sm.parcel_id spid,sp.parcel_sn spsn,sp.carrier_code spcarrier,sp.waybill spwaybill,sp.create_time spcreated,sp.dispatch_after spdue,sd.return_sn sdsn,sd.ticket_id sdticket,sd.dispatch_state sddispatch,sd.cancel_state sdcancel,sd.external_order sdexternal,sd.last_error sderror,sd.create_time sdcreated,sd.warehouse_status sdstatus,sd.pending_receipt_count sdpending,(SELECT COUNT(*) FROM wms_shared_return_member sc WHERE sc.company_code=sm.company_code AND sc.parcel_id=sm.parcel_id) spcount"+legacyColumns+" FROM "+(refund?"wms_refund_return":"wms_exchange_return")+" t LEFT JOIN wms_shared_return_member sm ON sm.company_code=t.company_code AND sm.id=t.shared_member_id LEFT JOIN wms_shared_return_parcel sp ON sp.company_code=sm.company_code AND sp.id=sm.parcel_id LEFT JOIN wms_shared_return_document sd ON sd.company_code=sp.company_code AND sd.parcel_id=sp.id"+legacy+" WHERE t.company_code=? AND t."+(refund?"plan_id":"exchange_id")+" IN ("+marks+") ORDER BY t.id LIMIT 2001",args.toArray());
            require(values.size()<=2000,"退回来源代次超过查询上限，请核对异常安排");for(Map<String,Object> t:values)out.add(normalize(kind,t));
        }attachInteractions(c,out);return out;
    }
    // One indexed lookup per bounded batch, including query failures that do not change dispatch state.
    void attachInteractions(String c,List<Map<String,Object>> rows){
        Set<String> numbers=new LinkedHashSet<>();for(Map<String,Object> row:rows)if(!text(row.get("return_sn")).isEmpty())numbers.add(text(row.get("return_sn")));
        List<String> all=new ArrayList<>(numbers);Map<String,Map<String,Object>> by=new HashMap<>();
        for(int at=0;at<all.size();at+=250){List<String> part=all.subList(at,Math.min(at+250,all.size()));List<Object> args=new ArrayList<>();args.add(c);args.addAll(part);args.add(c);
            String sql="SELECT l.id,l.ticket_sn,l.direction,l.action,l.request_id,l.result,l.error_info,l.result_summary,l.duration_ms,l.create_time,c.name connection_name,c.provider,c.environment FROM (SELECT MAX(id) id FROM wms_interaction_log WHERE company_code=? AND ticket_sn IN ("+String.join(",",Collections.nCopies(part.size(),"?"))+") GROUP BY ticket_sn) latest JOIN wms_interaction_log l ON l.id=latest.id AND l.company_code=? LEFT JOIN wms_connection c ON c.company_code=l.company_code AND c.id=l.connection_id";
            for(Map<String,Object> log:db.jdbc.queryForList(sql,args.toArray()))by.put(text(log.get("ticket_sn")),log);
        }
        Map<String,Long> finals=new HashMap<>();
        for(int at=0;at<all.size();at+=250){List<String> part=all.subList(at,Math.min(at+250,all.size()));String in=String.join(",",Collections.nCopies(part.size(),"?"));List<String> branches=new ArrayList<>();List<Object> args=new ArrayList<>();
            for(String prefix:Arrays.asList("wms_shared_return","wms_refund_parcel")){branches.add("SELECT d.return_sn,MAX(JSON_UNQUOTE(JSON_EXTRACT(r.payload,'$.complete'))='true') final_received FROM "+prefix+"_document d JOIN "+prefix+"_receipt r ON r.company_code=d.company_code AND r.parcel_id=d.parcel_id AND r.document_id=d.id WHERE d.company_code=? AND d.return_sn IN ("+in+") AND r.state<>'REJECTED' GROUP BY d.return_sn");args.add(c);args.addAll(part);}
            for(String t:Arrays.asList("wms_refund_return","wms_exchange_return")){branches.add("SELECT t.return_sn,MAX(e.final_confirmation) final_received FROM "+t+" t JOIN "+t+"_event e ON e.company_code=t.company_code AND e.task_id=t.id WHERE t.company_code=? AND t.return_sn IN ("+in+") GROUP BY t.return_sn");args.add(c);args.addAll(part);}
            for(Map<String,Object> r:db.jdbc.queryForList("SELECT return_sn,MAX(final_received) final_received FROM ("+String.join(" UNION ALL ",branches)+") f GROUP BY return_sn",args.toArray()))finals.put(text(r.get("return_sn")),n(r.get("final_received")));
        }
        for(Map<String,Object> row:rows){Map<String,Object> log=by.get(text(row.get("return_sn")));row.put("interaction",log==null?Collections.emptyMap():log);row.put("warehouse_final",finals.getOrDefault(text(row.get("return_sn")),0L));row.put("receipt_difference",n(row.get("warehouse_final"))>0&&n(row.get("accepted_quantity"))<n(row.get("quantity"))&&!"CONFIRMED".equals(row.get("cancel_state"))?1:0);formatTimes(row);}
    }
    static String warehouseState(Map<String,Object> row){String dispatch=text(row.get("dispatch_state")),cancel=text(row.get("cancel_state"));if(Arrays.asList("PENDING","UNKNOWN").contains(cancel))return "CANCEL_PENDING";if("REJECTED".equals(cancel))return "CANCEL_REJECTED";if("CONFIRMED".equals(cancel)||"CANCELED".equals(dispatch))return "CANCELED";if("ACCEPTED".equals(dispatch))return "ACCEPTED";if("FAILED".equals(dispatch))return "FAILED";if("UNKNOWN".equals(dispatch))return "UNKNOWN";if("SENDING".equals(dispatch))return "SENDING";return "UNSENT";}
    @SuppressWarnings("unchecked") static void formatTimes(Map<String,Object> row){for(Map.Entry<String,Object> entry:row.entrySet())if(entry.getValue() instanceof java.sql.Timestamp)entry.setValue(((java.sql.Timestamp)entry.getValue()).toLocalDateTime().format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));else if(entry.getValue() instanceof java.time.LocalDateTime)entry.setValue(((java.time.LocalDateTime)entry.getValue()).format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));else if(entry.getValue() instanceof Map)formatTimes((Map<String,Object>)entry.getValue());}
    Map<String,Object> normalize(String kind,Map<String,Object> t){
        boolean shared=n(t.get("spid"))>0,legacy=n(t.get("rpid"))>0;String prefix=shared?"sd":legacy?"rd":"";String sn=prefix.isEmpty()?text(t.get("return_sn")):text(t.get(prefix+"sn"));
        Map<String,Object> r=map("owner_kind",kind,"source_id",t.get("REFUND".equals(kind)?"plan_id":"exchange_id"),"part_key",kind+":"+t.get("id"),"generation",t.get("generation"),"task_id",t.get("id"),"warehouse_status",prefix.isEmpty()?t.get("warehouse_status"):t.get(prefix+"status"),"source_pending",n(t.get("source_pending")),"sku_sn",t.get("sku_sn"),"quantity",t.get("quantity"),"accepted_quantity",t.get("accepted_quantity"),"posted_quantity",t.get("posted_quantity"),"cancelled_quantity",t.get("cancelled_quantity"),"unit_cost",t.get("unit_cost"),"original_shipment_sn",t.get("original_shipment_sn"),"store_code",t.get("store_code"),"owner_code",t.get("owner_code"),"real_store_code",t.get("real_store_code"),"return_sn",sn,"ticket_id",prefix.isEmpty()?t.get("ticket_id"):t.get(prefix+"ticket"),"dispatch_state",prefix.isEmpty()?t.get("dispatch_state"):t.get(prefix+"dispatch"),"cancel_state",prefix.isEmpty()?t.get("cancel_state"):t.get(prefix+"cancel"),"external_order",prefix.isEmpty()?t.get("external_order"):t.get(prefix+"external"),"last_error",prefix.isEmpty()?t.get("last_error"):t.get(prefix+"error"),"receipt_state",t.get("receipt_state"),"source_created",t.get("create_time"),"document_created",prefix.isEmpty()?t.get("create_time"):t.get(prefix+"created"),"expected_members",shared?t.get("spcount"):legacy?t.get("rpcount"):1,"pending_count",shared?n(t.get("sdpending")):legacy?n(t.get("rppending")):0);
        r.put("warehouse_state",warehouseState(r));r.put("source_return_sn",t.get("return_sn"));r.put("parcel_key",shared?"SHARED:"+t.get("spid"):legacy?"REFUND:"+t.get("rpid"):"");r.put("parcel_sn",shared?t.get("spsn"):legacy?t.get("rpsn"):"");r.put("parcel_created",shared?t.get("spcreated"):legacy?t.get("rpcreated"):t.get("create_time"));r.put("dispatch_after",shared?t.get("spdue"):legacy?t.get("rpdue"):null);r.put("carrier",shared?t.get("spcarrier"):legacy?t.get("rpcarrier"):"");r.put("waybill",shared?t.get("spwaybill"):legacy?t.get("rpwaybill"):"");
        // Private RSL rows are source/cost ledgers, not additional warehouse commands.
        if(!shared&&!legacy&&text(t.get("return_sn")).startsWith("RSL"))r.put("return_sn","");
        for(Map.Entry<String,Object> entry:r.entrySet())if(entry.getValue() instanceof java.sql.Timestamp)entry.setValue(((java.sql.Timestamp)entry.getValue()).toLocalDateTime().format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));
        return r;
    }
}
